class RangeModule {
    map<int, int> intervals; // left -> right
public:
    RangeModule() {}

    void addRange(int left, int right) {
        auto it = intervals.upper_bound(left);
        if (it != intervals.begin()) {
            auto prev = std::prev(it);
            if (prev->second >= left) {
                left = prev->first;
                right = max(right, prev->second);
                intervals.erase(prev);
            }
        }
        while (it != intervals.end() && it->first <= right) {
            right = max(right, it->second);
            it = intervals.erase(it);
        }
        intervals[left] = right;
    }

    bool queryRange(int left, int right) {
        auto it = intervals.upper_bound(left);
        if (it == intervals.begin()) return false;
        auto prev = std::prev(it);
        return prev->second >= right;
    }

    void removeRange(int left, int right) {
        auto it = intervals.upper_bound(left);
        if (it != intervals.begin()) {
            auto prev = std::prev(it);
            if (prev->second > left) {
                if (prev->second > right) {
                    intervals[right] = prev->second;
                }
                prev->second = left;
            }
        }
        while (it != intervals.end() && it->first < right) {
            if (it->second > right) {
                intervals[right] = it->second;
            }
            it = intervals.erase(it);
        }
    }
};

import java.util.*;

class RangeModule {
    private TreeMap<Integer, Integer> map;

    public RangeModule() {
        map = new TreeMap<>();
    }

    public void addRange(int left, int right) {
        Integer start = map.floorKey(left);
        if (start != null && map.get(start) >= left) {
            left = start;
            right = Math.max(right, map.get(start));
        }
        Map<Integer, Integer> sub = map.subMap(left, true, right, true);
        Set<Integer> toRemove = new HashSet<>(sub.keySet());
        for (int k : toRemove) {
            right = Math.max(right, map.get(k));
            map.remove(k);
        }
        map.put(left, right);
    }

    public boolean queryRange(int left, int right) {
        Integer start = map.floorKey(left);
        if (start == null) return false;
        return map.get(start) >= right;
    }

    public void removeRange(int left, int right) {
        Integer start = map.floorKey(left);
        if (start != null && map.get(start) > left) {
            int prevEnd = map.get(start);
            map.put(start, left);
            if (prevEnd > right) {
                map.put(right, prevEnd);
            }
        }
        Map<Integer, Integer> sub = map.subMap(left, true, right, false);
        Set<Integer> toRemove = new HashSet<>(sub.keySet());
        for (int k : toRemove) {
            int end = map.get(k);
            map.remove(k);
            if (end > right) {
                map.put(right, end);
            }
        }
    }
}

var RangeModule = function() {
    this.intervals = [];
};

/** 
 * @param {number} left 
 * @param {number} right
 * @return {void}
 */
RangeModule.prototype.addRange = function(left, right) {
    const next = [];
    let inserted = false;
    for (const [l, r] of this.intervals) {
        if (r < left) {
            next.push([l, r]);
        } else if (l > right) {
            if (!inserted) {
                next.push([left, right]);
                inserted = true;
            }
            next.push([l, r]);
        } else {
            left = Math.min(left, l);
            right = Math.max(right, r);
        }
    }
    if (!inserted) next.push([left, right]);
    this.intervals = next;
};

/** 
 * @param {number} left 
 * @param {number} right
 * @return {boolean}
 */
RangeModule.prototype.queryRange = function(left, right) {
    let low = 0, high = this.intervals.length - 1;
    let idx = -1;
    while (low <= high) {
        const mid = (low + high) >> 1;
        if (this.intervals[mid][0] <= left) {
            idx = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return idx !== -1 && this.intervals[idx][1] >= right;
};

/** 
 * @param {number} left 
 * @param {number} right
 * @return {void}
 */
RangeModule.prototype.removeRange = function(left, right) {
    const next = [];
    for (const [l, r] of this.intervals) {
        if (r <= left || l >= right) {
            next.push([l, r]);
        } else {
            if (l < left) next.push([l, left]);
            if (r > right) next.push([right, r]);
        }
    }
    this.intervals = next;
};
